<script setup lang="ts">
import { useI18n } from 'vue-i18n';
import type { AgentWorkflowCodeAttempt, AgentWorkflowStepRun } from '@/api/agentWorkflows';
const props=defineProps<{ record?:AgentWorkflowStepRun; status:string }>();
const {t}=useI18n(); const tr=(key:string)=>t(`agentWorkflowCanvas.${key}`);
const pretty=(value:unknown)=>JSON.stringify(value,null,2);
function attemptState(attempt:AgentWorkflowCodeAttempt){if(attempt.error||attempt.execution?.error_code)return 'codeAttemptFailed';if(!attempt.finished_at)return ['interrupted','cancelled','failed'].includes(props.status)?'codeAttemptUnknown':'codeAttemptRunning';return 'codeAttemptCompleted';}
</script>
<template>
  <section class="aw-code-result" data-testid="workflow-code-result"><header><strong>{{tr('codeExecution')}}</strong><span>{{t(`agentWorkflow.status.${status}`)}}</span></header>
    <p v-if="record?.fallback_used" class="aw-code-recovered" data-testid="workflow-code-fallback-used">{{tr('codeFallbackUsed')}}</p>
    <p v-if="!record?.code_execution" class="aw-code-result-hint">{{tr(status==='interrupted'?'codeResultUnknown':'codeResultPending')}}</p>
    <template v-if="record?.code_execution"><dl><div><dt>{{tr('codeRuntime')}}</dt><dd>{{record.code_execution.runtime || record.code_execution.language}}</dd></div><div v-if="record.code_execution.duration_ms!==undefined"><dt>{{tr('duration')}}</dt><dd>{{record.code_execution.duration_ms}} ms</dd></div><div v-if="record.code_execution.exit_code!==undefined"><dt>{{tr('codeExit')}}</dt><dd>{{record.code_execution.exit_code}}</dd></div></dl><p v-if="record.code_execution.error_code" class="aw-code-result-error">{{record.code_execution.error_code}}<span v-if="record.code_execution.timed_out"> · {{tr('codeTimedOut')}}</span></p><code v-if="record.code_execution.source_sha256" class="aw-code-version" :title="record.code_execution.source_sha256">{{tr('codeFrozenSource')}} · {{record.code_execution.source_sha256.slice(0,10)}}</code></template>
    <section v-if="record?.code_inputs"><h4>{{tr('codeActualInputs')}}</h4><pre>{{pretty(record.code_inputs)}}</pre></section>
    <section v-if="record?.output"><h4>{{tr('codeActualOutputs')}}</h4><pre data-testid="workflow-code-output">{{pretty(record.output)}}</pre></section>
    <template v-if="record?.code_execution"><section v-for="stream in ['stdout','stderr'] as const" :key="stream"><h4>{{stream}} <small v-if="record.code_execution[`${stream}_truncated` as 'stdout_truncated'|'stderr_truncated']">{{tr('codeLogsTruncated')}}</small></h4><pre :data-testid="`workflow-code-${stream}`">{{record.code_execution[stream] || tr('codeNoLogs')}}</pre></section></template>
    <section v-if="record?.attempts?.length" class="aw-code-attempts" data-testid="workflow-code-attempts"><h4>{{tr('codeAttempts')}}</h4><details v-for="attempt in record.attempts" :key="attempt.number"><summary>{{tr('codeAttempt')}} {{attempt.number}} · {{tr(attemptState(attempt))}}</summary><p v-if="attempt.error" class="aw-code-result-error">{{attempt.error}}</p><p v-if="attempt.execution?.error_code" class="aw-code-result-error">{{attempt.execution.error_code}}</p><pre v-if="attempt.output">{{pretty(attempt.output)}}</pre><template v-if="attempt.execution"><section v-for="stream in ['stdout','stderr'] as const" :key="stream"><h4>{{stream}} <small v-if="attempt.execution[`${stream}_truncated` as 'stdout_truncated'|'stderr_truncated']">{{tr('codeLogsTruncated')}}</small></h4><pre>{{attempt.execution[stream]||tr('codeNoLogs')}}</pre></section></template></details></section>
    <p v-if="record?.summary" class="aw-code-result-hint">{{record.summary}}</p>
  </section>
</template>
<style scoped>
.aw-code-result{display:flex;flex-direction:column;gap:11px;min-width:0;border-top:1px solid var(--el-border-color-lighter);padding-top:12px}.aw-code-result header{display:flex;justify-content:space-between;gap:10px;font-size:12px}.aw-code-result header span,.aw-code-result-hint{font-size:11px;color:var(--el-text-color-secondary);line-height:1.65;margin:0}.aw-code-result dl{display:flex;flex-wrap:wrap;gap:12px;margin:0;font-size:11px}.aw-code-result dt{color:var(--el-text-color-secondary)}.aw-code-result dd{margin:4px 0 0}.aw-code-result h4{font-size:11px;margin:0 0 5px}.aw-code-result h4 small{color:var(--el-color-warning);font-weight:400}.aw-code-result pre{margin:0;padding:9px;border-radius:7px;background:var(--el-fill-color-light);font:11px/1.65 ui-monospace,SFMono-Regular,Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;max-height:230px;overflow:auto}.aw-code-result-error{font-size:11px;color:var(--el-color-danger);margin:0}.aw-code-recovered{padding:8px;border-radius:7px;background:var(--el-color-warning-light-9);color:var(--el-color-warning);font-size:11px;line-height:1.65}.aw-code-attempts details{border:1px solid var(--el-border-color-lighter);border-radius:7px;padding:8px;margin:7px 0;font-size:11px}.aw-code-attempts summary{cursor:pointer}.aw-code-attempts section{margin-top:8px}.aw-code-version{font-size:10px;overflow-wrap:anywhere;color:var(--el-text-color-secondary)}
</style>
